using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Windows.Forms;using System.Web.Script.Serialization;
namespace MonitorSlice {
static class MirrorIntegration {
 [StructLayout(LayoutKind.Sequential)]struct Mouse{public int X,Y;public uint Data,Flags,Time;public IntPtr Extra;}
 [StructLayout(LayoutKind.Sequential)]struct Input{public uint Type;public Mouse Value;}
 [StructLayout(LayoutKind.Explicit,Size=40)]struct Key{[FieldOffset(0)]public uint Type;[FieldOffset(8)]public ushort Code;[FieldOffset(10)]public ushort Scan;[FieldOffset(12)]public uint Flags;}
 [DllImport("user32.dll")]static extern uint SendInput(uint count,Input[] events,int size);
 [DllImport("user32.dll",EntryPoint="SendInput")]static extern uint Keys(uint count,Key[] events,int size);
 [DllImport("user32.dll")]static extern bool GetCursorPos(out Native.Point p);
 [DllImport("MonitorSlice.Capture.dll",CallingConvention=CallingConvention.Cdecl)]static extern int SampleCapturePixel(IntPtr handle,int x,int y,out uint color);
 static void Wait(int ms){var end=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
 public static void Run(){Directory.CreateDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence"));var log=new List<object>();bool passed=false;var before=Ccd.Read(false);var json=new JavaScriptSerializer();var physical=Displays.All().Where(d=>d.Attached&&!Displays.Virtual().Any(v=>v.Name==d.Name)).ToArray();var session=new VirtualSession();try{var testRegions=new[]{new Rectangle(0,0,100,100),new Rectangle(100,20,80,60)};Check(MirrorPointer.Constrain(new Point(-500,50),testRegions)==new Point(0,50),"화면 왼쪽 경계 제한 실패");Check(MirrorPointer.Constrain(new Point(500,50),testRegions)==new Point(179,50),"화면 오른쪽 경계 제한 실패");Check(MirrorPointer.Constrain(new Point(105,-100),testRegions)==new Point(99,0),"빈 공간 좌표 제한 실패");session.Recover();foreach(var selected in (Environment.CommandLine.Contains("--quick")?physical.Take(1):physical.AsEnumerable())){var target=new Rectangle(selected.Mode.X,selected.Mode.Y,selected.Mode.Width,selected.Mode.Height);foreach(var layout in (Environment.CommandLine.Contains("--quick")?new[]{"grid"}:Layouts.Keys)){var forms=new List<Form>();try{File.AppendAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","mirror-progress.txt"),DateTime.UtcNow.ToString("o")+" start "+selected.Name+" "+layout+Environment.NewLine);session.Start(target,Layouts.Create(layout),true);Wait(400);Check(Displays.Virtual().Count(d=>d.Attached)==session.Views.Count-1,"추가 가상 화면 수 오류");var fields=new List<TextBox>();var wheels=new List<int>();foreach(var view in session.Views){var f=new Form{Text="MirrorIntegration",AutoScaleMode=AutoScaleMode.None,FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,BackColor=Color.Red};var field=new TextBox{Location=new Point(20,20),Size=new Size(200,40)};int wheelIndex=wheels.Count;wheels.Add(0);field.MouseWheel+=delegate{wheels[wheelIndex]++;};f.Controls.Add(field);f.Show();Native.ShowWindowAsync(f.Handle,5);Native.SetWindowPos(f.Handle,new IntPtr(-1),view.Source.X,view.Source.Y,Math.Min(view.Source.Width,600),Math.Min(view.Source.Height,400),0x210);forms.Add(f);fields.Add(field);}session.RaiseOutput();Wait(600);for(int i=0;i<forms.Count;i++){var v=session.Views[i];var point=PointerBridge.Map(new Point(v.Source.X+60,v.Source.Y+35),v.Source,v.Destination);session.Input.MoveVisual(point);Wait(100);SendInput(2,new[]{new Input{Value=new Mouse{Flags=2}},new Input{Value=new Mouse{Flags=4}}},Marshal.SizeOf(typeof(Input)));Wait(150);Check(fields[i].Focused,"클릭 포커스 실패: "+layout+" / "+i);Keys(2,new[]{new Key{Type=1,Code=0x4D},new Key{Type=1,Code=0x4D,Flags=2}},40);Wait(100);Check(fields[i].Text.Equals("m",StringComparison.OrdinalIgnoreCase),"키보드 전달 실패");Keys(2,new[]{new Key{Type=1,Scan=0xD55C,Flags=4},new Key{Type=1,Scan=0xD55C,Flags=6}},40);Wait(80);SendInput(1,new[]{new Input{Value=new Mouse{Flags=0x800,Data=120}}},Marshal.SizeOf(typeof(Input)));Wait(80);Check(wheels[i]>0,"휠 전달 실패");var visualBefore=session.Input.VisualPosition;SendInput(1,new[]{new Input{Value=new Mouse{X=6,Y=0,Flags=1,Extra=new IntPtr(0x4D53)}}},Marshal.SizeOf(typeof(Input)));Wait(80);Check(session.Input.VisualPosition.X>visualBefore.X,"이동 훅 경로 실패");if(v.Destination.Bottom<target.Bottom){session.Input.MoveVisual(new Point(v.Destination.X+v.Destination.Width/2,v.Destination.Bottom-2));session.Input.MoveRelative(0,8);Check(session.Input.VisualPosition.Y>=v.Destination.Bottom,"칸 아래 경계 이동 실패");}bool dragging=false,dragged=false;var drag=new Panel{Location=new Point(20,100),Size=new Size(180,80)};drag.MouseDown+=delegate{dragging=true;drag.Capture=true;};drag.MouseMove+=delegate{if(dragging)dragged=true;};drag.MouseUp+=delegate{dragging=false;drag.Capture=false;};forms[i].Controls.Add(drag);session.Input.MoveVisual(PointerBridge.Map(new Point(v.Source.X+50,v.Source.Y+130),v.Source,v.Destination));Wait(80);SendInput(1,new[]{new Input{Value=new Mouse{Flags=2}}},Marshal.SizeOf(typeof(Input)));Wait(80);session.Input.MoveVisual(PointerBridge.Map(new Point(v.Source.X+100,v.Source.Y+150),v.Source,v.Destination));Wait(80);SendInput(1,new[]{new Input{Value=new Mouse{Flags=4}}},Marshal.SizeOf(typeof(Input)));Wait(80);Check(dragged&&!dragging,"드래그 전달 실패");foreach(var color in new[]{Color.Lime,Color.Blue}){forms[i].BackColor=color;forms[i].Refresh();Wait(300);uint sampled;Marshal.ThrowExceptionForHR(SampleCapturePixel(v.Capture,250,200,out sampled));var actual=Color.FromArgb(unchecked((int)sampled));Check(Math.Abs(actual.R-color.R)+Math.Abs(actual.G-color.G)+Math.Abs(actual.B-color.B)<30,"화면 갱신 실패: "+layout+" / "+i+" expected="+color+" actual="+actual);}}var other=physical.FirstOrDefault(d=>d.Name!=selected.Name);if(other!=null){var point=new Point(other.Mode.X+50,other.Mode.Y+50);session.Input.MoveVisual(point);Wait(80);Native.Point actual;GetCursorPos(out actual);Check(new Rectangle(other.Mode.X,other.Mode.Y,other.Mode.Width,other.Mode.Height).Contains(actual.X,actual.Y),"다른 물리 모니터 진입 실패");}var savedPoint=session.Input.VisualPosition;session.Input.MoveVisual(new Point(target.Right+100000,target.Bottom+100000));var allowed=physical.Select(d=>new Rectangle(d.Mode.X,d.Mode.Y,d.Mode.Width,d.Mode.Height));Check(allowed.Any(r=>r.Contains(session.Input.VisualPosition)),"보이지 않는 좌표가 누적됨");session.Input.MoveVisual(savedPoint);var start=session.PerViewFrames;foreach(var f in forms){f.BackColor=Color.Yellow;f.Refresh();}Wait(600);Check(session.RenderErrors.All(e=>e==0),"출력 엔진 오류");log.Add(new{Monitor=selected.Name,Layout=layout,Views=session.Views.Count,Clicks=fields.Count,Keyboard=fields.Count,Backend=session.Backend,VisibleBoundsConstrained=true,PointerScale=PointerSettings.Scale,LiveColors=true,UnicodePacketDelivered=fields.All(field=>field.Text.Contains("한")),Wheel=true,Drag=true,RelativeHook=true,OtherPhysicalMonitor=true,Errors=session.RenderErrors});}finally{foreach(var f in forms)f.Dispose();session.Stop();Wait(200);}Check(json.Serialize(Ccd.Read(false))==json.Serialize(before),"원래 디스플레이 구성 복원 실패");}}passed=true;}finally{session.Stop();string file=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","mirror-integration.json");Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,json.Serialize(new{Passed=passed,Checks=log,Restored=json.Serialize(Ccd.Read(false))==json.Serialize(before)}));}}
}
}
